function syncResearch(){const p=researchCandidate?.provenance,d=D.provenance,compatible=!d||(p&&p.configuration_sha256===d.configuration_sha256&&p.engine_sha256===d.engine_sha256&&p.calendar?.version===d.calendar?.version);historical=researchCandidate?.model===MODEL&&D.model===MODEL&&compatible?researchCandidate:null;}
async function load(){const hadSnapshot=D.status==='ready';try{const request=Date.now();let base=DATA_ROOT,nextChartIndex=null;try{const active=await fetch(DATA_ROOT+`current.json?request=${request}`,{cache:'no-store'});if(active.ok){const manifest=await active.json();if(manifest.schema===1&&typeof manifest.base==='string'&&!manifest.base.includes('..')&&!manifest.base.startsWith('/')){base=DATA_ROOT+manifest.base;nextChartIndex=typeof manifest.charts==='string'&&!manifest.charts.includes('..')?manifest.charts:null;}}}catch{/* Legacy snapshots have no activation manifest. */}const [snapshot,status]=await Promise.all([fetch(base+`latest.json?request=${request}`,{cache:'no-store'}),fetch(base+`health.json?request=${request}`,{cache:'no-store'}).catch(()=>null)]);if(!snapshot.ok)throw Error('Market snapshot unavailable');const next=await snapshot.json();if(next.schema!==1||!Array.isArray(next.rows)||!Array.isArray(next.themes))throw Error('Unsupported market snapshot');if(next.policy?.benchmark!=='^CRSLDX'||next.model!==MODEL)throw Error('Industry-ranked model snapshot pending');D=next;snapshotBase=base;chartIndexPath=nextChartIndex;chartIndex=null;loadedChartFiles=new Set();const nextHealth=status?.ok?await status.json():{};health=nextHealth.status==='error'||!nextHealth.snapshot_id||!D.snapshot_id||nextHealth.snapshot_id===D.snapshot_id?nextHealth:{};charts=null;syncResearch();render();}catch(e){health={status:'error',snapshot_id:D.snapshot_id,message:`Browser refresh failed: ${e.message}`};if(!hadSnapshot)D={rows:[],themes:[],tracking:[],summary:[],status:'awaiting_first_scan'};render();}}

