$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('File is too large');const j=JSON.parse(await file.text());if(j.version!==1||!j.workspace||typeof j.workspace!=='object'||Array.isArray(j.workspace))throw Error('Not a Stocks workspace export');const safe={};for(const [id,p] of Object.entries(j.workspace)){if(!/^[A-Z0-9]{12}$/.test(id)||!p||typeof p!=='object')continue;safe[id]={watch:p.watch===true,review:['reviewed','dismissed','unreviewed'].includes(p.review)?p.review:'unreviewed',note:String(p.note||'').slice(0,10000),symbol:String(p.symbol||'').slice(0,50)};}workspace={...workspace,...safe};save();if(Array.isArray(j.custom_symbols)){customSymbols=normalizeSymbols(j.custom_symbols.join(','));saveCustom();}render();toast('Workspace imported.');}catch(err){toast('Import failed: '+err.message);}e.target.value='';};
function normalizeSymbols(text){const ignored=new Set(['SYMBOL','SYMBOLS','TICKER','TICKERS','NSE','BSE']);const seen=new Set(),out=[];for(let token of String(text).split(/[\s,;\t|]+/)){token=token.trim().replace(/^['"]|['"]$/g,'').toUpperCase();const bse=token.startsWith('BSE:');token=token.replace(/^(NSE|BSE):/,'').replace(/\.NS$/,'');if(!token||ignored.has(token)||!/^[A-Z0-9&-]{1,30}$/.test(token))continue;token=bse?'BSE:'+token:token;if(seen.has(token))continue;seen.add(token);out.push(token);}return out;}
$('custom-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('File is too large');const parsed=normalizeSymbols(await file.text());if(!parsed.length)throw Error('No valid symbol tokens were found');customSymbols=parsed;saveCustom();bulkScope=null;render();const matched=currentGroupRows().length;toast(`${parsed.length} symbols loaded · ${matched} eligible NSE symbols analysed`);}catch(err){toast('Symbol import failed: '+err.message);}e.target.value='';};
