async function loadResearch(){try{const r=await fetch(DATA_ROOT+'backtest/report.json',{cache:'no-store'});if(!r.ok)return;const result=await r.json();if(result.schema===1&&result.status==='complete'&&result.benchmark?.ticker==='^CRSLDX'){researchCandidate=result;syncResearch();renderHistorical();}}catch{/* Keep the explicit awaiting-result state. */}}
function renderHistorical(){const target=$('historical-research');if(!target)return;
 const opportunity=$('historical-upside');
 if(opportunity)opportunity.innerHTML=historical?`<h3>Historical upside after detection</h3><p class="section-note">Held-out period ${esc(historical.ranges.holdout[0])} to ${esc(historical.ranges.holdout[1])} · ${esc(historical.selected_variant)} rules · next-session open. These are historical observations, not probabilities for today's candidates. Longer horizons have different evaluated samples.</p><div class="table-wrap"><table><thead><tr><th>Sessions</th><th>Evaluated / detected</th><th>Reached +5%</th><th>Reached +10%</th><th>Median best high</th><th>Median worst low</th></tr></thead><tbody>${historical.results.holdout.map(s=>`<tr><td>${s.horizon}</td><td>${s.n} / ${s.detections}</td><td>${rate(s.reach_5pct)}</td><td>${rate(s.reach_10pct)}</td><td>${pct(s.median_mfe)}</td><td>${pct(s.median_mae)}</td></tr>`).join('')}</tbody></table></div><p class="section-note">Best high does not assume you can sell at the top. Missing prices and immature horizons are excluded from hit rates, not counted as wins. Historical universe survival and overlapping signals limit the evidence.</p><h3>Live detections going forward</h3>`:'';

 if(!historical){target.innerHTML='<div class="section-heading"><div><span class="eyebrow">FIVE-YEAR HISTORICAL RESEARCH</span><h2>Does the move continue after detection?</h2></div></div><div class="empty"><strong>The industry-ranked model is awaiting its own published result.</strong><p>The previous model’s report is deliberately not relabelled. The new run will use five years of next-session entries, industry-relative candidate ranking, trading costs and Nifty 500 outcome comparisons.</p></div>';return;}
 const r=historical,v=r.selected_variant,full=r.ranges.full,hold=r.ranges.holdout,stats=r.results.holdout,twenty=stats.find(x=>x.horizon===20),pf=r.portfolios[v].holdout,epf=r.exit_portfolios?.[v]?.holdout;
 const variants=Object.entries(r.variants).map(([name,s])=>`<tr><td>${esc(name.replaceAll('_',' '))}${name===v?' · selected on validation':''}</td><td>${pct(s.development.mean_excess_yield_adjusted)}</td><td>${pct(s.validation.mean_excess_yield_adjusted)}</td><td>${pct(s.holdout.mean_excess_yield_adjusted)}</td><td>${s.holdout.n}</td></tr>`).join('');
 target.innerHTML=`<div class="section-heading"><div><span class="eyebrow">FIVE-YEAR HISTORICAL RESEARCH</span><h2>Does the move continue after detection?</h2></div><a class="text-button" href="https://github.com/jalanaditya30/Stocks/blob/main/research/PROTOCOL.md" target="_blank" rel="noopener">Evaluation rules ↗</a></div><p class="section-note">Replay: ${esc(full[0])} to ${esc(full[1])}. Untouched test: ${esc(hold[0])} to ${esc(hold[1])}. Benchmark: Nifty 500 price index. Current surviving registry: ${r.coverage.downloaded}/${r.coverage.registry} histories downloaded.</p><div class="notice">${esc(r.conclusion)} Stock returns include adjusted dividends; the index is price-only. The selection test also adds an assumed 2% annual benchmark yield. This is not an official total-return-index comparison.</div><h3>Untouched test · ${esc(v.replaceAll('_',' '))}</h3><p class="section-note">Entries use the next session’s open; returns deduct 0.25% each side. Win rate means a positive net return at the stated horizon. It is not a probability assigned to today’s stocks.</p><div class="table-wrap"><table><thead><tr><th>Holding period</th><th>Resolved signals</th><th>Net win rate</th><th>Beat Nifty 500</th><th>Median net return</th><th>Median excess</th></tr></thead><tbody>${stats.map(s=>`<tr><td>${s.horizon} sessions</td><td>${s.n}</td><td>${rate(s.win_rate)}</td><td>${rate(s.beat_rate)}</td><td class="${color(s.median_net)}">${pct(s.median_net)}</td><td class="${color(s.median_excess)}">${pct(s.median_excess)}</td></tr>`).join('')}</tbody></table></div><div class="detail-columns"><div><h3>Room after detection · 20 sessions</h3><p class="section-note">${rate(twenty?.reach_10pct)} reached a high at least 10% above entry. Median best subsequent high: ${pct(twenty?.median_mfe)}. Median worst low: ${pct(twenty?.median_mae)}. The best high is an opportunity statistic, not a realised sale or a price target.</p></div><div><h3>Deploying finite capital · test period</h3><p class="section-note">Ten cash sleeves; at most two holdings per industry; 20-session exits. Strategy CAGR: <b>${pct(pf?.cagr)}</b>; index CAGR: <b>${pct(pf?.benchmark_cagr)}</b> (${pct(pf?.benchmark_cagr_yield_adjusted)} with the assumed yield). Strategy drawdown: ${pct(pf?.max_drawdown)}. Average invested: ${rate(pf?.average_exposure)}.</p></div></div><h3>Your dual-negative exit overlay</h3><p class="section-note">${epf?`Exit after a completed close where both VStop and OBV MACD are bearish, executed at the next available open with 0.25% cost each side. Strategy CAGR: <b>${pct(epf.cagr)}</b>; drawdown: ${pct(epf.max_drawdown)}; median holding: ${num(epf.median_holding_sessions)} sessions; average invested: ${rate(epf.average_exposure)}; Nifty 500 CAGR: ${pct(epf.benchmark_cagr)} (${pct(epf.benchmark_cagr_yield_adjusted)} with assumed yield).`:'This separately specified exit test is awaiting a completed historical run. The fixed 20-session result above must not be presented as your exit rule.'} This overlay was added after the entry-model research and is descriptive, not a fresh untouched validation.</p><h3>All predeclared alternatives · 20-session mean excess</h3><p class="section-note">These figures include the assumed benchmark-yield allowance. A research alternative is not automatically promoted to live rules.</p><div class="table-wrap"><table><thead><tr><th>Variant</th><th>Development</th><th>Validation</th><th>Untouched test</th><th>Test observations</th></tr></thead><tbody>${variants}</tbody></table></div><p class="section-note">95% interval for selected test mean excess: ${twenty?.excess_ci95?twenty.excess_ci95.map(x=>pct(x)).join(' to '):'insufficient independent months'}. Resampling uses entry months. Missing historical prices and immature horizons remain unresolved in the audit records.</p><details class="research-limitations"><summary>Coverage, biases and reproducible results</summary><ul>${r.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><a href="${DATA_ROOT}backtest/report.json" target="_blank" rel="noopener">Full results JSON</a> · <a href="${DATA_ROOT}backtest/trades.csv.gz" target="_blank" rel="noopener">Download every historical observation</a></p></details><hr class="research-divider">`;
}
